<?php
namespace App\Http\Controllers; use App\Models\TeachingReport; use App\Notifications\AfhmNotification; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class TeachingReportController extends Controller { public function index(Request $r){$q=TeachingReport::with('teacher');$u=$r->user();if($u->role==='teacher')$q->where('teacher_id',$u->id);if($u->role==='supervisor')$q->whereIn('teacher_id',$u->supervisedTeachers()->pluck('id'));$reports=$q->when($r->report_type,fn($x,$v)=>$x->where('report_type',$v))->when($r->teacher_id,fn($x,$v)=>$x->where('teacher_id',$v))->latest('submitted_at')->paginate(15)->withQueryString();return view('reports.index',compact('reports'));} public function create(){return view('reports.form');} public function store(Request $r){$d=$r->validate(['report_type'=>'required|in:weekly,monthly','title'=>'required|string|max:200','content'=>'required|string','attachment'=>'nullable|file|mimes:pdf,doc,docx,ppt,pptx,jpg,jpeg,png|max:10240']);$d['teacher_id']=$r->user()->id;$d['submitted_at']=now();if($r->hasFile('attachment'))$d['file_path']=$r->file('attachment')->store('reports');$report=TeachingReport::create($d);$r->user()->supervisor?->notify(new AfhmNotification("{$r->user()->name} submitted {$report->report_type} report.",route('reports.show',$report)));return redirect()->route('reports.show',$report)->with('success','Teaching report submitted successfully.');} public function show(Request $r,TeachingReport $report){$u=$r->user();abort_if($u->role==='teacher'&&$report->teacher_id!==$u->id,403);abort_if($u->role==='supervisor'&&$report->teacher?->supervisor_id!==$u->id,403);return view('reports.show',compact('report'));} public function download(Request $r,TeachingReport $report){$this->show($r,$report);abort_unless($report->file_path&&Storage::exists($report->file_path),404);return Storage::download($report->file_path);}}
